mapper.select:
SELECT 
FROM iam_notification_log

    realm_id = #{realmId} AND deleted = FALSE
    AND channel = #{channel}
    AND status = #{status}

        AND recipient LIKE '%' || #{recipient} || '%'

    AND template_code = #{templateCode}
    AND created_time >= #{fromTime}
    AND created_time <= #{toTime}

ORDER BY created_time DESC, id DESC

mapper.delete:
DELETE FROM iam_notification_log
WHERE id IN (
    SELECT id
    FROM iam_notification_log
    WHERE created_time < #{cutoff}
    ORDER BY id
    LIMIT #{limit}
)

mapper.select:
SELECT COUNT(*)
FROM iam_notification_log
WHERE realm_id = #{realmId}
  AND recipient = #{recipient}
  AND deleted = FALSE
  AND created_time >= CURRENT_TIMESTAMP - (#{minutes} * INTERVAL '1 minute')
